import {api,donationsReady} from './donations-api.js?v=20261103-2';
import {donationsConfig} from './donations-config.js';
import {products as staticProducts} from './catalog.js';
const $=id=>document.getElementById(id);
const el=(tag,cls='',text='')=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text)n.textContent=text;return n;};
const button=(label,cls,fn)=>{const n=el('button',cls,label);n.type='button';n.addEventListener('click',fn);return n;};
const region=$('result-region'),searchPanel=$('search-panel'),adminButton=$('validator-open');
let currentPerson=null,currentTeam=null,authToken='',adminEmail='',returnToProfessional=null;
function show(node){searchPanel.hidden=true;region.replaceChildren(node);window.scrollTo({top:0,behavior:'instant'});}
function back(){searchPanel.hidden=false;if(returnToProfessional)returnToProfessional();else region.replaceChildren();}
function shell(kicker,title){const box=el('section','donation-panel');box.append(el('p','section-kicker',kicker),el('h2','',title));return box;}
function notice(box,text,kind=''){let n=box.querySelector('.donation-notice');if(!n){n=el('p','donation-notice');box.prepend(n);}n.className='donation-notice '+kind;n.textContent=text;}
function setBusy(btn,value,label){btn.disabled=value;btn.textContent=value?'Salvando…':label;}
function parseQuantity(value){if(!/^(0|[1-9]\d*)$/.test(value)||Number(value)>1000000||!Number.isSafeInteger(Number(value)))throw new Error('Use somente quantidades inteiras de 0 a 1.000.000.');return Number(value);}
function quantityRow(product,initial,onChange,declared=null){
  const row=el('div','product-row'),description=el('div','product-description');description.append(el('strong','',product.nome||product.name),el('small','',`${product.referencia||product.reference} · ${product.pontos||product.unitPoints} pontos por unidade`));
  if(declared!==null)description.append(el('small','declared-label',`Declarado: ${declared}`));
  const controls=el('div','quantity-controls'),input=el('input');input.type='number';input.inputMode='numeric';input.min='0';input.max='1000000';input.step='1';input.value=String(initial);input.setAttribute('aria-label',`Quantidade de ${product.nome||product.name}`);
  const minus=button('−','quantity-button',()=>{const q=parseQuantity(input.value);input.value=String(Math.max(0,q-1));onChange();});
  const plus=button('+','quantity-button',()=>{const q=parseQuantity(input.value);input.value=String(Math.min(1000000,q+1));onChange();});
  input.addEventListener('input',onChange);controls.append(minus,input,plus);
  const subtotal=el('strong','item-subtotal','0 pontos');row.append(description,controls,subtotal);
  return {row,input,subtotal,id:product.id||product.productId,points:product.pontos||product.unitPoints};
}
function recalc(rows,total){let sum=0;for(const row of rows){try{const q=parseQuantity(row.input.value);const pts=q*row.points;row.subtotal.textContent=`${pts} pontos`;sum+=pts;row.input.setCustomValidity('');}catch(e){row.input.setCustomValidity(e.message);row.subtotal.textContent='—';total.textContent='Corrija as quantidades';return false;}}total.textContent=`${sum} pontos`;return true;}
function getCatalog(){return staticProducts;}
export function setProfessional(person,team,renderAgain){currentPerson=person;currentTeam=team;returnToProfessional=renderAgain;}
export function professionalActions(){if(!donationsReady||!currentPerson)return null;const actions=el('div','professional-actions');actions.append(button('Cadastrar doação','primary-button',()=>openDonation()),button('Doações validadas','secondary-button',()=>openHistory()));return actions;}
async function openDonation(){
  const person=currentPerson,team=currentTeam,box=shell('Doação de alimentos','Cadastrar doação');box.append(el('p','donation-context',`${person.nome} · ${team.nome}`),el('p','muted','Informe unidades das referências indicadas. A pontuação é prevista e depende da conferência do Serviço Social.'));
  const list=el('div','product-list'),total=el('strong','total-points','0 pontos'),footer=el('div','donation-footer');box.append(list,el('p','total-label','Total previsto'),total,footer);const backButton=button('Voltar','secondary-button',back);footer.append(backButton);show(box);
  try{const products=getCatalog();const rows=products.map(p=>quantityRow(p,0,()=>recalc(rows,total)));rows.forEach(r=>list.append(r.row));const key=crypto.randomUUID();const save=button('Salvar doação','primary-button',async()=>{
    if(!recalc(rows,total)){notice(box,'Corrija as quantidades.','error');return;}const items=rows.map(r=>({produtoId:r.id,quantidade:parseQuantity(r.input.value)})).filter(i=>i.quantidade>0);if(!items.length){notice(box,'Selecione ao menos um alimento.','error');return;}
    setBusy(save,true,'Salvar doação');backButton.disabled=true;try{const result=await api('createDonation',{professionalId:person.id,idempotencyKey:key,items});const done=shell('Cadastro concluído','Doação cadastrada!');done.append(el('p','donation-protocol',result.protocol),el('p','','Doação cadastrada! Leve sua doação até o Serviço Social para validação.'),el('p','projected-label',`${result.points} pontos previstos`),button('Nova doação','primary-button',()=>openDonation()),button('Voltar à equipe','secondary-button',back));show(done);}catch(e){notice(box,e.message,'error');}finally{setBusy(save,false,'Salvar doação');backButton.disabled=false;}
  });footer.prepend(save);
  }catch(e){notice(box,e.message,'error');}
}
async function openHistory(){const person=currentPerson,box=shell('Histórico','Doações validadas');box.append(el('p','donation-context',person.nome),button('Voltar','secondary-button',back));show(box);notice(box,'Carregando histórico…');try{const data=await api('validatedDonations',{professionalId:person.id});box.querySelector('.donation-notice').remove();box.append(el('p','confirmed-total',`Total confirmado: ${data.totalConfirmed} pontos`));if(!data.donations.length)box.append(el('p','muted','Ainda não há doações validadas.'));for(const d of data.donations){const card=el('article','donation-record');card.append(el('h3','',d.protocol),el('p','',`${new Date(d.createdAt).toLocaleString('pt-BR')} · ${d.confirmedPoints} pontos confirmados`));for(const item of d.items.filter(i=>i.received>0))card.append(el('p','',`${item.name}: ${item.received} ${item.reference} · ${item.confirmedPoints} pontos`));box.append(card);}}catch(e){notice(box,e.message,'error');}}
function loadGoogle(){return new Promise((resolve,reject)=>{if(window.google?.accounts?.id)return resolve();const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.onload=resolve;script.onerror=()=>reject(new Error('Login Google indisponível.'));document.head.append(script);});}
async function openAdmin(){const box=shell('Serviço Social','Validar doações');box.append(button('Voltar','secondary-button',back));show(box);if(authToken){renderAdmin(box);return;}notice(box,'Carregando login Google…');try{await loadGoogle();box.querySelector('.donation-notice').remove();const login=window.google.accounts.oauth2.initCodeClient({client_id:donationsConfig.googleClientId,scope:'openid email',ux_mode:'popup',callback:async response=>{notice(box,'Conferindo autorização…');try{const result=await api('authorize',{code:response.code});authToken=result.sessionToken;adminEmail=result.email;renderAdmin(box);}catch(e){notice(box,e.message,'error');}}});box.append(button('Entrar com Google','primary-button',()=>login.requestCode()));}catch(e){notice(box,e.message,'error');}}
async function signOut(){const token=authToken;authToken='';adminEmail='';try{await api('logout',{},token);}catch(e){console.warn('Falha ao encerrar sessão remota:',e);}openAdmin();}
function renderAdmin(box){box.replaceChildren(el('p','section-kicker','Serviço Social'),el('h2','','Consultar doações'),el('p','muted',`Conta autorizada: ${adminEmail}`),button('Sair da conta','secondary-button',signOut));const form=el('form','admin-search'),input=el('input');input.type='search';input.placeholder='Nome do profissional ou protocolo';input.required=true;input.minLength=2;input.setAttribute('aria-label','Nome ou protocolo');const submit=el('button','primary-button','Pesquisar');submit.type='submit';form.append(input,submit);const list=el('div','admin-results');box.append(form,list);form.addEventListener('submit',async e=>{e.preventDefault();submit.disabled=true;list.textContent='Buscando…';try{const data=await api('pending',{query:input.value},authToken);list.replaceChildren();if(!data.donations.length)list.textContent='Nenhuma doação encontrada.';for(const d of data.donations){const card=button(`${d.protocol} · ${d.professionalName} · ${new Date(d.createdAt).toLocaleString('pt-BR')} · ${d.status==='VALIDADA'?'validada':'aguardando validação'}`,'option',()=>openReview(d.id,d.status==='VALIDADA'));list.append(card);}}catch(err){list.textContent=err.message;}finally{submit.disabled=false;}});}
async function openReview(id,correction=false){const box=shell('Serviço Social',correction?'Corrigir doação':'Conferir doação');box.append(button('Voltar à busca','secondary-button',openAdmin));show(box);notice(box,'Carregando doação…');try{const [d,products]=await Promise.all([api('detail',{donationId:id},authToken),getCatalog()]);box.querySelector('.donation-notice').remove();box.append(el('p','donation-context',`${d.professionalName} · ${d.teamName}`),el('p','donation-protocol',d.protocol),el('p','muted',`Previsto: ${d.projectedPoints} pontos · Confirmado: ${d.confirmedPoints} pontos`));const list=el('div','product-list'),total=el('strong','total-points','0 pontos');box.append(list,el('p','total-label','Pontos a confirmar'),total);let rows=[];const update=()=>recalc(rows,total);for(const item of d.items){const row=quantityRow(item,item.received===null?item.declared:item.received,update,item.declared);rows.push(row);list.append(row.row);}const extras=products.filter(p=>!d.items.some(i=>i.productId===p.id));const extraSelect=el('select','extra-select');extraSelect.append(new Option('Incluir alimento não declarado',''));extras.forEach(p=>extraSelect.append(new Option(p.nome,p.id)));box.append(extraSelect);extraSelect.addEventListener('change',()=>{const p=extras.find(x=>x.id===extraSelect.value);if(!p)return;const row=quantityRow(p,0,update,0);rows.push(row);list.append(row.row);extraSelect.querySelector(`option[value="${p.id}"]`).remove();extraSelect.value='';update();});update();let reason;if(correction){reason=el('textarea','reason');reason.placeholder='Justificativa da correção (mínimo de 10 caracteres)';reason.maxLength=500;box.append(reason);}const save=button(correction?'Salvar correção':'Salvar validação','primary-button',async()=>{if(!recalc(rows,total)){notice(box,'Corrija as quantidades.','error');return;}save.disabled=true;try{const result=await api(correction?'correct':'validate',{donationId:id,version:d.version,operationKey:operationKey,items:rows.map(r=>({produtoId:r.id,quantidade:parseQuantity(r.input.value)})),reason:reason?.value||''},authToken);notice(box,`${result.protocol} salvo: ${result.confirmedPoints} pontos confirmados.`,'success');save.remove();const personId=result.professionalId;const person=currentData?.profissionais?.find(p=>p.id===personId);if(person){currentPerson=person;currentTeam=currentData.equipes.find(t=>t.id===person.equipeId);box.append(button('Ver profissional','primary-button',()=>{back();selectProfessional?.(person);}));}}catch(e){notice(box,e.message,'error');save.disabled=false;}});const operationKey=crypto.randomUUID();box.append(save);}catch(e){notice(box,e.message,'error');}}
let currentData=null,selectProfessional=null;export function initDonations(data,onSelect){currentData=data;selectProfessional=onSelect;if(donationsReady){adminButton.hidden=false;adminButton.addEventListener('click',openAdmin);}}
